package cn.zhuatech.recruitai.controller; import cn.zhuatech.recruitai.common.ApiResponse; import cn.zhuatech.recruitai.service.CandidateMatchService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/ai") @PreAuthorize("hasAnyRole('DOMAIN_USER','DOMAIN_OPERATOR','ADMIN')") public class AiFeatureController { private final CandidateMatchService service; public AiFeatureController(CandidateMatchService service){this.service=service;} @PostMapping("/candidate/match") public ApiResponse<CandidateMatchService.Result> execute(@Valid @RequestBody CandidateMatchService.Request request){return ApiResponse.ok("候选人与职位可解释匹配完成",service.match(request));} }